from typing import AnyStr, Iterable, List, Dict, Union
from collections.abc import Mapping, Sequence

class SQLParams:
    in_style: str

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    formatted_sql = sql
    converted_params = []

    for params in many_params:
        if isinstance(params, Mapping):
            converted_params.append({k: v for k, v in params.items() if k in self.SQLParams.in_style})
        elif isinstance(params, Sequence):
            converted_params.append([v for v in params if v in self.SQLParams.in_style])

    return formatted_sql, converted_params
