def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    current_tag = None

    for char in text:
        if char == '<':
            in_code_block = True
            current_tag = None
        elif char == '>':
            in_code_block = False
            if current_tag:
                tags.add(current_tag)
                if replacer:
                    current_tag = replacer(current_tag)
        elif not in_code_block:
            if char == '[':
                current_tag = ''
            elif current_tag and char == ']':
                current_tag += char
            elif current_tag:
                current_tag += char

    return tags, text
